#include <iostream>
#include <vector>
#include <optional>
#include <cstddef>

// Returns index wrapped in std::optional if found, std::nullopt otherwise
std::optional<std::size_t> linearSearch(const std::vector<int>& arr, int key) {
    for (std::size_t i = 0; i < arr.size(); ++i) {
        if (arr[i] == key) {
            return i;
        }
    }
    return std::nullopt;
}

int main() {
    const std::size_t SIZE = 10;
    std::vector<int> a(SIZE);
    for (std::size_t x = 0; x < SIZE; ++x) {
        a[x] = static_cast<int>(2 * x);
    }

    int searchKey = 12;
    if (auto index = linearSearch(a, searchKey); index.has_value()) {
        std::cout << "Found value at index " << *index << "\n";
    } else {
        std::cout << "Value not found\n";
    }

    searchKey = 15;
    if (auto index = linearSearch(a, searchKey); index.has_value()) {
        std::cout << "Found value at index " << *index << "\n";
    } else {
        std::cout << "Value not found\n";
    }

    return 0;
}

#include <iostream>
#include <vector>
#include <iomanip>
#include <cstddef>

void printHeader(std::size_t size) {
    std::cout << "\nIndices:\n";
    for (std::size_t i = 0; i < size; ++i) {
        std::cout << std::setw(3) << i << ' ';
    }
    std::cout << '\n';
    for (std::size_t i = 0; i < 4 * size; ++i) {
        std::cout << '-';
    }
    std::cout << '\n';
}

void printRow(const std::vector<int>& b, std::ptrdiff_t low, std::ptrdiff_t mid, std::ptrdiff_t high) {
    for (std::ptrdiff_t i = 0; i < static_cast<std::ptrdiff_t>(b.size()); ++i) {
        if (i < low || i > high) {
            std::cout << "    ";
        } else if (i == mid) {
            std::cout << std::setw(3) << b[static_cast<std::size_t>(i)] << '*';
        } else {
            std::cout << std::setw(3) << b[static_cast<std::size_t>(i)] << ' ';
        }
    }
    std::cout << '\n';
}

std::ptrdiff_t binarySearch(const std::vector<int>& b, int searchKey, std::ptrdiff_t low, std::ptrdiff_t high) {
    while (low <= high) {
        std::ptrdiff_t middle = low + (high - low) / 2;
        printRow(b, low, middle, high);

        if (searchKey == b[static_cast<std::size_t>(middle)]) {
            return middle;
        } else if (searchKey < b[static_cast<std::size_t>(middle)]) {
            high = middle - 1;
        } else {
            low = middle + 1;
        }
    }
    return -1;
}

int main() {
    const std::size_t SIZE = 15;
    std::vector<int> a(SIZE);
    for (std::size_t i = 0; i < SIZE; ++i) {
        a[i] = static_cast<int>(2 * i);
    }

    int key = 8;
    printHeader(SIZE);
    std::ptrdiff_t result = binarySearch(a, key, 0, static_cast<std::ptrdiff_t>(SIZE - 1));

    if (result != -1) {
        std::cout << "\n" << key << " found at index " << result << "\n";
    } else {
        std::cout << "\n" << key << " not found\n";
    }

    return 0;
}
